+        } else if (strcmp(argv[i], "-t") == 0) {
+            if (i + 1 < argc) {
+                tty = argv[++i];
+                tty_set = 1;
+            } else {
+                print_usage();
+                exit(0);
+            }
+        } else {
+            print_usage();
+            exit(0);
+        }
+    }
+}
+
+int main(int argc, char *argv[]) {
+    parse_args(argc, argv);
+    
+    if (x_window_mode) {
+        printf("X window mode not supported in this build.\n");
+        return 1;
+    }
+    
+    if (tty_set) {
+        printf("cmatrix: error: '%s' couldn't be opened: No such file or directory.\n", tty);
+        return 1;
+    }
+    
+    printf("Error opening terminal: unknown.\n");
+    return 1;
+}
